    correctKey: 'D',
    explanation: '支持力公式は基礎形状ごとの形状係数補正が不可欠。形状を無視して同一式を適用できるという記述は誤り。\n【図解】テルツァギーの支持力公式\n　qu＝c・Nc＋q・Nq＋0.5・γ・B・Nγ（連続基礎の場合）★\n　Nc・Nq・Nγはφの関数、φ大→係数大\n　○根入れ深さ増→q項増→支持力増\n　×「形状係数を考慮せず同一式適用」は誤り★\n　→正方形・円形基礎では形状係数補正が必要',
    difficulty: 'advanced',
