    correctKey: 'D',
    explanation: 'プレテンション（打設前に緊張・付着で伝達、主に工場製品）とポストテンション（硬化後に緊張・定着、現場施工の大型構造物）は原理が異なる。同一視は誤り。\n【図解】プレテンション方式とポストテンション方式\n　プレテンション：打設前に鋼材を緊張→硬化後解放→付着で応力伝達★（主に工場製品）\n　ポストテンション：硬化後にシース内鋼材を緊張・定着★（現場施工の大型構造物向け）\n　○ポストテンションはグラウト注入で防食・一体化\n　×「両者は同一原理で区別不要」は誤り★',
